INSERT INTO tmp_v52_questions(type, question, options_json, correct_answer, explanation, difficulty) VALUES
('multiple','¿Cuáles son las cuatro edades de la Historia después de la Prehistoria?',CAST('["Edad Antigua, Edad Media, Edad Moderna y Edad Contemporánea", "Paleolítico, Neolítico, Edad de los Metales y Edad Media", "Invierno, primavera, verano y otoño", "Infancia, juventud, adultez y vejez"]' AS JSON),'Edad Antigua, Edad Media, Edad Moderna y Edad Contemporánea','Después de la Prehistoria, la Historia se divide en Edad Antigua, Edad Media, Edad Moderna y Edad Contemporánea.',1),
('multiple','¿Con qué hecho comienza la Edad Antigua?',CAST('["Con la invención de la escritura", "Con el descubrimiento de América", "Con la Revolución francesa", "Con la aparición de Internet"]' AS JSON),'Con la invención de la escritura','La Edad Antigua comienza cuando aparece la escritura, aproximadamente hacia el 3500 a. C.',1),
('multiple','¿En qué año termina la Edad Antigua?',CAST('["476 d. C.", "1492 d. C.", "1789 d. C.", "2026 d. C."]' AS JSON),'476 d. C.','La Edad Antigua termina en el año 476 d. C., con la caída del Imperio romano de Occidente.',1),
('multiple','¿Qué edad va desde el año 476 d. C. hasta 1492 d. C.?',CAST('["Edad Media", "Edad Antigua", "Edad Moderna", "Edad Contemporánea"]' AS JSON),'Edad Media','La Edad Media comienza en 476 d. C. y termina en 1492 d. C.',1),
('multiple','¿Con qué hecho se suele señalar el final de la Edad Media en 4º de Primaria?',CAST('["El descubrimiento de América", "La invención del teléfono", "La invención de la escritura", "La llegada a la Luna"]' AS JSON),'El descubrimiento de América','En muchos libros escolares se toma 1492, descubrimiento de América, como final de la Edad Media.',1),
('multiple','¿Qué edad comienza en 1492 d. C.?',CAST('["Edad Moderna", "Edad Antigua", "Edad Media", "Prehistoria"]' AS JSON),'Edad Moderna','La Edad Moderna empieza en 1492 d. C.',1),
('multiple','¿En qué año termina la Edad Moderna?',CAST('["1789 d. C.", "476 d. C.", "1492 d. C.", "3500 a. C."]' AS JSON),'1789 d. C.','La Edad Moderna termina en 1789 d. C., con la Revolución francesa.',1),
('multiple','¿Qué edad llega hasta nuestros días?',CAST('["Edad Contemporánea", "Edad Media", "Edad Antigua", "Neolítico"]' AS JSON),'Edad Contemporánea','La Edad Contemporánea comienza en 1789 y continúa hasta la actualidad.',1),
('text','Completa: a. C. significa...',NULL,'antes de cristo','a. C. significa antes de Cristo.',1),
('text','Completa: d. C. significa...',NULL,'después de cristo|despues de cristo','d. C. significa después de Cristo.',1),
('multiple','¿Cuántos años tiene un lustro?',CAST('["5", "10", "100", "1.000"]' AS JSON),'5','Un lustro son 5 años.',1),
('multiple','¿Cuántos años tiene una década?',CAST('["10", "5", "100", "1.000"]' AS JSON),'10','Una década son 10 años.',1),
('multiple','¿Cuántos años tiene un siglo?',CAST('["100", "10", "5", "1.000"]' AS JSON),'100','Un siglo son 100 años.',1),
('multiple','¿Cuántos años tiene un milenio?',CAST('["1.000", "100", "10", "5"]' AS JSON),'1.000','Un milenio son 1.000 años.',1),
('multiple','¿A qué siglo pertenece el año 1492?',CAST('["Siglo XV", "Siglo XIV", "Siglo XVI", "Siglo XX"]' AS JSON),'Siglo XV','1492 pertenece al siglo XV porque está entre 1401 y 1500.',2),
('multiple','¿A qué siglo pertenece el año 1789?',CAST('["Siglo XVIII", "Siglo XVII", "Siglo XIX", "Siglo XXI"]' AS JSON),'Siglo XVIII','1789 pertenece al siglo XVIII porque está entre 1701 y 1800.',2),
('multiple','¿A qué siglo pertenece el año 2026?',CAST('["Siglo XXI", "Siglo XX", "Siglo XIX", "Siglo XVIII"]' AS JSON),'Siglo XXI','2026 pertenece al siglo XXI porque está entre 2001 y 2100.',2),
('multiple','¿Cuál de estas fechas es más antigua?',CAST('["1000 a. C.", "500 a. C.", "100 d. C.", "2026 d. C."]' AS JSON),'1000 a. C.','En las fechas antes de Cristo, el número mayor indica una fecha más antigua.',2),
('multiple','¿Cuál de estas fechas es más reciente?',CAST('["2026 d. C.", "1492 d. C.", "476 d. C.", "500 a. C."]' AS JSON),'2026 d. C.','En las fechas después de Cristo, el número mayor indica una fecha más reciente.',1),
