INSERT INTO questions(topic_id,type,question,options_json,correct_answer,explanation,difficulty) SELECT @topic_mates12,'multiple','¿Cuál de estas es una experiencia de azar?','["Tirar una moneda y ver si sale cara o cruz", "Escribir la fecha de hoy", "Leer una palabra conocida", "Sumar 2 + 2"]','Tirar una moneda y ver si sale cara o cruz','Es una experiencia de azar porque antes de lanzar no sabemos qué resultado saldrá.',1 FROM DUAL WHERE @topic_mates12 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM questions WHERE topic_id=@topic_mates12 AND question='¿Cuál de estas es una experiencia de azar?');
