INSERT INTO topics(subject, course, title, description, content) SELECT 'Conocimiento del Medio','4º Primaria Andalucía','Tema 8 · Cómo han cambiado nuestros hábitos','Fuentes históricas, Prehistoria, edades de la Historia, romanos, fechas clave y cambios en la forma de vida.','# Tema 8 · Cómo han cambiado nuestros hábitos
INSERT INTO questions(topic_id,type,question,options_json,correct_answer,explanation,difficulty) VALUES
(@topic8,'multiple','¿Qué son las fuentes históricas?','["Pistas del pasado que nos dan información", "Cuentas de multiplicar", "Juegos de azar", "Partes de una planta"]','Pistas del pasado que nos dan información','Las fuentes históricas son restos, documentos, objetos o testimonios que ayudan a conocer el pasado.',1),
(@topic8,'multiple','¿Cuál es una fuente escrita?','["Una carta antigua", "Una herramienta de piedra", "Una pintura rupestre", "Un hueso fósil"]','Una carta antigua','Las cartas son fuentes escritas porque usan la escritura.',1),
(@topic8,'multiple','¿Cuál es una fuente material?','["Una moneda romana", "Una canción popular", "Una noticia actual", "Una entrevista de radio"]','Una moneda romana','Una moneda es un objeto y por eso es una fuente material.',1),
(@topic8,'multiple','¿Cuál es una fuente gráfica?','["Un mapa antiguo", "Una leyenda contada por los abuelos", "Un hacha de piedra", "Una vasija"]','Un mapa antiguo','Los mapas, fotografías, dibujos y pinturas son fuentes gráficas.',1),
(@topic8,'multiple','¿Cuál es una fuente oral?','["Una leyenda contada de palabra", "Una moneda", "Un periódico", "Una muralla"]','Una leyenda contada de palabra','Las fuentes orales transmiten información mediante la palabra hablada.',1),
(@topic8,'text','Nombra una fuente escrita.',NULL,'carta|libro|periódico|periodico|documento|inscripción|inscripcion','Son fuentes escritas porque contienen escritura.',1),
(@topic8,'text','Nombra una fuente no escrita.',NULL,'herramienta|moneda|cerámica|ceramica|hueso|pintura|mapa|fotografía|fotografia|leyenda|canción|cancion','Las fuentes no escritas pueden ser materiales, gráficas u orales.',1),
(@topic8,'multiple','¿Por qué en la Prehistoria usamos sobre todo fuentes no escritas?','["Porque aún no se había inventado la escritura", "Porque no existían animales", "Porque no había piedras", "Porque todos escribían libros"]','Porque aún no se había inventado la escritura','La Prehistoria termina cuando aparece la escritura; por eso se estudia con restos no escritos.',2),
(@topic8,'multiple','¿Cuáles son las tres etapas de la Prehistoria?','["Paleolítico, Neolítico y Edad de los Metales", "Edad Antigua, Media y Moderna", "Roma, Grecia y Egipto", "Década, siglo y milenio"]','Paleolítico, Neolítico y Edad de los Metales','La Prehistoria se divide en esas tres grandes etapas.',1),
(@topic8,'multiple','¿Cómo vivían las personas del Paleolítico?','["Eran nómadas y cazadoras-recolectoras", "Vivían en grandes ciudades modernas", "Tenían fábricas y trenes", "Usaban internet para comerciar"]','Eran nómadas y cazadoras-recolectoras','En el Paleolítico se desplazaban buscando alimento y recursos.',1),
(@topic8,'multiple','¿Qué significa nómada?','["Que se desplaza y no vive siempre en el mismo sitio", "Que vive siempre en una ciudad fija", "Que trabaja solo el hierro", "Que escribe documentos"]','Que se desplaza y no vive siempre en el mismo sitio','Los grupos nómadas cambiaban de lugar según sus necesidades.',1),
(@topic8,'multiple','¿Qué descubrimiento ayudó a cocinar, calentarse e iluminar en el Paleolítico?','["El fuego", "La escritura", "La imprenta", "El teléfono"]','El fuego','El fuego fue muy importante para la vida diaria en el Paleolítico.',1),
(@topic8,'text','¿Con qué materiales fabricaban herramientas en el Paleolítico?',NULL,'piedra madera y hueso|piedra, madera y hueso|con piedra madera y hueso|con piedras madera y huesos','Fabricaban herramientas con materiales naturales como piedra, madera y hueso.',1),
(@topic8,'multiple','¿Qué es el arte rupestre?','["Pinturas o grabados en paredes de cuevas", "Un tipo de periódico", "Una moneda romana", "Un mapa de carreteras"]','Pinturas o grabados en paredes de cuevas','El arte rupestre muestra escenas de animales y de la vida cotidiana en cuevas.',1),
(@topic8,'multiple','¿Qué aprendieron las personas en el Neolítico?','["A producir sus alimentos con agricultura y ganadería", "A construir coches", "A escribir periódicos", "A navegar por internet"]','A producir sus alimentos con agricultura y ganadería','La agricultura y la ganadería cambiaron mucho la forma de vivir.',1),
(@topic8,'multiple','¿Qué significa sedentario?','["Que vive de forma estable en un lugar", "Que se mueve continuamente", "Que solo caza animales", "Que no usa herramientas"]','Que vive de forma estable en un lugar','En el Neolítico muchas personas se hicieron sedentarias y formaron poblados.',1),
(@topic8,'text','Nombra los dos grandes descubrimientos del Neolítico.',NULL,'agricultura y ganadería|agricultura y ganaderia','La agricultura y la ganadería permitieron producir alimentos.',1),
(@topic8,'multiple','¿Dónde solían construir los primeros poblados del Neolítico?','["Cerca de ríos o fuentes de agua", "En el fondo del mar", "Lejos de toda agua", "Encima de nubes"]','Cerca de ríos o fuentes de agua','Necesitaban agua para vivir, cultivar y cuidar animales.',1),
(@topic8,'multiple','¿Qué cultivaban en el Neolítico?','["Cereales y legumbres", "Ordenadores y teléfonos", "Coches y trenes", "Piedras y metales"]','Cereales y legumbres','Los cultivos básicos eran cereales y legumbres.',1),
(@topic8,'multiple','¿Qué animales empezaron a domesticar?','["Ovejas, cabras, cerdos y perros", "Dinosaurios y ballenas", "Tigres y leones solamente", "Águilas y tiburones"]','Ovejas, cabras, cerdos y perros','Domesticaron animales útiles para alimento, ayuda y compañía.',1),
(@topic8,'multiple','¿Para qué servía la cerámica en el Neolítico?','["Para guardar alimentos y líquidos", "Para hacer pantallas", "Para construir carreteras romanas", "Para escribir periódicos"]','Para guardar alimentos y líquidos','La cerámica ayudó a almacenar comida y agua.',1),
(@topic8,'multiple','¿Cómo empezó la Edad de los Metales?','["Con la metalurgia", "Con la invención del teléfono", "Con el descubrimiento de América", "Con la Revolución francesa"]','Con la metalurgia','La metalurgia es obtener y trabajar metales.',1),
(@topic8,'multiple','¿Qué es la metalurgia?','["El arte de obtener y trabajar metales", "El cultivo de cereales", "La pintura en cuevas", "El estudio de mapas"]','El arte de obtener y trabajar metales','La metalurgia permitió fabricar objetos mejores con cobre, bronce y hierro.',1),
(@topic8,'multiple','¿Qué tres metales se trabajaron en esta etapa?','["Cobre, bronce e hierro", "Oro, plata y plástico", "Madera, piedra y hueso", "Agua, fuego y aire"]','Cobre, bronce e hierro','En la Edad de los Metales destacaron cobre, bronce e hierro.',1),
(@topic8,'multiple','¿Qué nuevo oficio apareció con más fuerza en la Edad de los Metales?','["Artesanos especializados", "Programadores", "Pilotos de avión", "Periodistas digitales"]','Artesanos especializados','Al trabajar metales y fabricar objetos surgieron oficios especializados.',2),
(@topic8,'multiple','¿Qué favoreció el contacto entre lugares y culturas en la Edad de los Metales?','["El comercio y la navegación", "La televisión", "Los videojuegos", "Las redes sociales"]','El comercio y la navegación','El comercio y la navegación ayudaron a intercambiar productos e ideas.',1),
(@topic8,'multiple','¿Qué construyeron algunos poblados en la Edad de los Metales para defenderse?','["Murallas", "Piscinas", "Ascensores", "Autopistas"]','Murallas','Muchos poblados crecieron y se protegieron con murallas.',1),
(@topic8,'multiple','¿Qué son los monumentos megalíticos?','["Construcciones con grandes piedras", "Libros escritos en latín", "Herramientas de plástico", "Barcos romanos"]','Construcciones con grandes piedras','Dólmenes y menhires son ejemplos de monumentos megalíticos.',1),
(@topic8,'text','Nombra un monumento megalítico.',NULL,'dolmen|menhir','Dólmenes y menhires son monumentos hechos con grandes piedras.',1),
(@topic8,'multiple','¿Qué poblado de Almería destaca en la Edad del Cobre?','["Los Millares", "Itálica", "Corduba", "Baelo Claudia"]','Los Millares','Los Millares fue un poblado importante de la Edad del Cobre en Almería.',2),
(@topic8,'multiple','¿Qué cultura de Almería pertenece a la Edad del Bronce?','["El Argar", "Los Millares", "La Viña", "Hispalis"]','El Argar','El Argar fue una cultura destacada de la Edad del Bronce.',2),
(@topic8,'multiple','¿Cuándo comienza la Historia?','["Con la invención de la escritura", "Con el nacimiento de internet", "Con los coches", "Con el descubrimiento del fuego"]','Con la invención de la escritura','La Historia comienza cuando aparece la escritura.',1),
(@topic8,'multiple','¿Hacia qué fecha se inventó la escritura?','["3500 a. C.", "1492 d. C.", "1789 d. C.", "2026 d. C."]','3500 a. C.','La escritura apareció aproximadamente hacia el 3500 a. C.',2),
(@topic8,'multiple','¿Qué significa a. C.?','["Antes de Cristo", "Después de Cristo", "Antes de Cádiz", "Año Contemporáneo"]','Antes de Cristo','a. C. se usa para fechas anteriores al año 1.',1),
(@topic8,'multiple','¿Qué significa d. C.?','["Después de Cristo", "Durante Castilla", "Desde Cádiz", "Década completa"]','Después de Cristo','d. C. se usa para fechas posteriores al año 1.',1),
(@topic8,'multiple','¿Cuántos años tiene un lustro?','["5", "10", "100", "1000"]','5','Un lustro son cinco años.',1),
(@topic8,'multiple','¿Cuántos años tiene una década?','["10", "5", "100", "1000"]','10','Una década son diez años.',1),
(@topic8,'multiple','¿Cuántos años tiene un siglo?','["100", "10", "1000", "50"]','100','Un siglo son cien años.',1),
(@topic8,'multiple','¿Cuántos años tiene un milenio?','["1000", "100", "10", "5"]','1000','Un milenio son mil años.',1),
(@topic8,'multiple','¿A qué siglo pertenece el año 1492?','["Siglo XV", "Siglo XIV", "Siglo XVI", "Siglo XXI"]','Siglo XV','El año 1492 está entre 1401 y 1500, por eso es siglo XV.',2),
(@topic8,'multiple','¿A qué siglo pertenece el año 1789?','["Siglo XVIII", "Siglo XVII", "Siglo XIX", "Siglo XV"]','Siglo XVIII','El año 1789 está entre 1701 y 1800, por eso es siglo XVIII.',2),
(@topic8,'multiple','¿A qué siglo pertenece el año 2026?','["Siglo XXI", "Siglo XX", "Siglo XIX", "Siglo XVIII"]','Siglo XXI','El año 2026 está entre 2001 y 2100, por eso es siglo XXI.',1),
(@topic8,'multiple','¿Cuáles son las edades de la Historia después de la Prehistoria?','["Edad Antigua, Edad Media, Edad Moderna y Edad Contemporánea", "Paleolítico, Neolítico y Metales", "Lustro, década y siglo", "Cobre, bronce y hierro"]','Edad Antigua, Edad Media, Edad Moderna y Edad Contemporánea','Después de la Prehistoria se estudian esas cuatro edades históricas.',1),
(@topic8,'multiple','¿Con qué comienza la Edad Antigua?','["Con la escritura", "Con América", "Con la Revolución francesa", "Con internet"]','Con la escritura','La Edad Antigua empieza con la aparición de la escritura.',1),
(@topic8,'multiple','¿En qué año termina la Edad Antigua?','["476 d. C.", "1492 d. C.", "1789 d. C.", "3500 a. C."]','476 d. C.','La Edad Antigua termina en 476 d. C. con la caída del Imperio romano de Occidente.',2),
(@topic8,'multiple','¿Qué ocurrió en el año 476 d. C.?','["Cayó el Imperio romano de Occidente", "Colón llegó a América", "Comenzó la Revolución francesa", "Se inventó la escritura"]','Cayó el Imperio romano de Occidente','Ese hecho marca el final de la Edad Antigua y el inicio de la Edad Media.',2),
(@topic8,'multiple','¿Cuándo llegaron los romanos a la Península Ibérica?','["218 a. C.", "1492 d. C.", "711 d. C.", "1789 d. C."]','218 a. C.','Los romanos llegaron a la Península Ibérica durante la Segunda Guerra Púnica, en 218 a. C.',3),
(@topic8,'multiple','¿En qué año terminó la conquista romana de Hispania?','["19 a. C.", "476 d. C.", "1492 d. C.", "3500 a. C."]','19 a. C.','La conquista romana de Hispania terminó en el 19 a. C.',3),
(@topic8,'multiple','¿Qué construyeron los romanos?','["Calzadas, puentes, acueductos, teatros y ciudades", "Solo cuevas y chozas", "Ordenadores y teléfonos", "Monumentos de plástico"]','Calzadas, puentes, acueductos, teatros y ciudades','Los romanos dejaron muchas obras públicas y ciudades.',1),
(@topic8,'multiple','¿Cómo se llamaba una provincia romana importante en Andalucía?','["Bética", "Galia", "Britania", "Lusitania solamente"]','Bética','La Bética fue una provincia romana muy importante en el sur de Hispania.',2),
(@topic8,'multiple','¿Cuál fue una ciudad romana importante en Andalucía?','["Itálica", "Nueva York", "París", "Machu Picchu"]','Itálica','Itálica fue una ciudad romana situada cerca de la actual Sevilla.',1),
(@topic8,'multiple','¿Qué otras ciudades romanas destacan en Andalucía?','["Corduba, Gades, Hispalis y Baelo Claudia", "Granada, América y París", "Roma, Egipto y China", "Cádiz, Marte y Venus"]','Corduba, Gades, Hispalis y Baelo Claudia','Son ejemplos de ciudades o lugares romanos importantes en Andalucía.',3),
(@topic8,'multiple','¿Qué ocurrió en el año 711 d. C.?','["Comenzó la presencia musulmana en la Península Ibérica", "Colón llegó a América", "Cayó Roma", "Se inventó la escritura"]','Comenzó la presencia musulmana en la Península Ibérica','En 711 comenzó la presencia musulmana en la Península Ibérica.',3),
(@topic8,'multiple','¿Qué edad va desde 476 hasta 1492?','["Edad Media", "Edad Antigua", "Edad Moderna", "Edad Contemporánea"]','Edad Media','La Edad Media va desde la caída de Roma hasta 1492.',1),
(@topic8,'multiple','¿Qué ocurrió en 1492?','["Colón llegó a América y terminó la Edad Media", "Se inventó el fuego", "Llegaron los romanos", "Empezó la Edad Contemporánea"]','Colón llegó a América y terminó la Edad Media','1492 es una fecha clave: llegada a América y paso a la Edad Moderna.',2),
(@topic8,'multiple','¿Quién llegó a América en 1492?','["Cristóbal Colón", "Julio César", "Napoleón", "Homo sapiens"]','Cristóbal Colón','Cristóbal Colón llegó a América en 1492.',1),
(@topic8,'multiple','¿Qué edad comienza en 1492?','["Edad Moderna", "Edad Media", "Edad Antigua", "Paleolítico"]','Edad Moderna','1492 marca el inicio de la Edad Moderna.',1),
(@topic8,'multiple','¿Qué edad comienza en 1789?','["Edad Contemporánea", "Edad Moderna", "Edad Media", "Neolítico"]','Edad Contemporánea','La Edad Contemporánea empieza con la Revolución francesa en 1789.',2),
(@topic8,'multiple','¿Qué ocurrió en 1789?','["La Revolución francesa", "La llegada de Colón a América", "La caída de Roma", "La llegada de los romanos a Hispania"]','La Revolución francesa','1789 marca el inicio de la Edad Contemporánea.',2),
(@topic8,'multiple','Ordena correctamente de más antiguo a más moderno.','["Paleolítico, Neolítico, Edad de los Metales, Edad Antigua", "Edad Moderna, Paleolítico, Neolítico, Edad Antigua", "Edad Antigua, Neolítico, Paleolítico, Metales", "Edad Contemporánea, Edad Media, Paleolítico, Neolítico"]','Paleolítico, Neolítico, Edad de los Metales, Edad Antigua','Esa es la secuencia temporal correcta entre Prehistoria e Historia.',2),
(@topic8,'multiple','¿Qué opción resume mejor el cambio del Paleolítico al Neolítico?','["Pasaron de buscar alimentos a producirlos", "Pasaron de escribir libros a usar ordenadores", "Dejaron de vivir en la Tierra", "Perdieron todas sus herramientas"]','Pasaron de buscar alimentos a producirlos','El gran cambio fue producir alimentos con agricultura y ganadería.',2),
