  item_key VARCHAR(80) NOT NULL UNIQUE,
  category VARCHAR(60) NOT NULL,
  title VARCHAR(160) NOT NULL,
  description TEXT NULL,
  icon VARCHAR(16) NOT NULL DEFAULT '⭐',
