CREATE TABLE IF NOT EXISTS manual_homeworks (
  id INT AUTO_INCREMENT PRIMARY KEY,
  title VARCHAR(180) NOT NULL,
  subject VARCHAR(120) NOT NULL,
  instructions TEXT NULL,
  assigned_user_id INT NOT NULL,
  created_by INT NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_manual_homeworks_user (assigned_user_id, active),
  CONSTRAINT fk_manual_hw_user FOREIGN KEY (assigned_user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS manual_homework_questions (
  id INT AUTO_INCREMENT PRIMARY KEY,
  homework_id INT NOT NULL,
  order_no INT NOT NULL DEFAULT 1,
  question_text TEXT NOT NULL,
  expected_answer TEXT NULL,
  explanation TEXT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_manual_hwq_homework (homework_id, order_no),
  CONSTRAINT fk_manual_hwq_homework FOREIGN KEY (homework_id) REFERENCES manual_homeworks(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS manual_homework_attempts (
  id INT AUTO_INCREMENT PRIMARY KEY,
  homework_id INT NOT NULL,
  user_id INT NOT NULL,
  total_questions INT NOT NULL DEFAULT 0,
  correct_questions INT NOT NULL DEFAULT 0,
  score DECIMAL(4,2) NOT NULL DEFAULT 0,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_manual_attempt_user (user_id, created_at),
  CONSTRAINT fk_manual_attempt_homework FOREIGN KEY (homework_id) REFERENCES manual_homeworks(id) ON DELETE CASCADE,
  CONSTRAINT fk_manual_attempt_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS manual_homework_answers (
  id INT AUTO_INCREMENT PRIMARY KEY,
  attempt_id INT NOT NULL,
  question_id INT NOT NULL,
  student_answer TEXT NULL,
  ai_correct TINYINT(1) NOT NULL DEFAULT 0,
  admin_correct TINYINT(1) NULL,
  final_correct TINYINT(1) NOT NULL DEFAULT 0,
  feedback TEXT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_manual_answer_attempt (attempt_id),
  CONSTRAINT fk_manual_answer_attempt FOREIGN KEY (attempt_id) REFERENCES manual_homework_attempts(id) ON DELETE CASCADE,
  CONSTRAINT fk_manual_answer_question FOREIGN KEY (question_id) REFERENCES manual_homework_questions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

