SELECT 'Francés','5º Primaria Andalucía','Saludos y presentación','Primer tema base de francés: saludos, despedidas y frases sencillas.','Bonjour significa hola o buenos días. Salut significa hola de forma informal. Merci significa gracias. Au revoir significa adiós. Je m’appelle... significa me llamo... Comment ça va ? significa ¿cómo estás? En 5º conviene empezar con vocabulario oral, frases cortas y pronunciación sencilla.'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE subject='Francés' AND title='Saludos y presentación');

SELECT t.id,'multiple','¿Qué significa “bonjour”?','["gracias","hola / buenos días","adiós","por favor"]','hola / buenos días','Bonjour se usa para saludar durante el día.',1 FROM topics t WHERE t.subject='Francés' AND t.title='Saludos y presentación'
AND NOT EXISTS (SELECT 1 FROM questions q WHERE q.topic_id=t.id AND q.question='¿Qué significa “bonjour”?');

SELECT t.id,'text','Traduce al español: merci',NULL,'gracias','Merci significa gracias.',1 FROM topics t WHERE t.subject='Francés' AND t.title='Saludos y presentación'
AND NOT EXISTS (SELECT 1 FROM questions q WHERE q.topic_id=t.id AND q.question='Traduce al español: merci');

SELECT t.id,'multiple','¿Cuál es una despedida en francés?','["au revoir","hello","school","cat"]','au revoir','Au revoir significa adiós.',1 FROM topics t WHERE t.subject='Francés' AND t.title='Saludos y presentación'
AND NOT EXISTS (SELECT 1 FROM questions q WHERE q.topic_id=t.id AND q.question='¿Cuál es una despedida en francés?');


